# Stories for albums 401–450 (long format agreed with the owner: three paragraphs + a listening tip,
# ~220 words per story, three picks with ~12-word notes). Original Hebrew; facts checked on the web, uncertain ones softened.
# Used by tools/batches/build_401_450.py; later edits: python3 tools/apply_stories.py stories_401_450
STORIES = {}
def add(n, story, picks): STORIES[n] = {'story': story, 'picks': picks}

add(401, [
'''הג׳אם, שלישייה מווקינג שבדרום אנגליה, הגיעו עם גל הפאנק של 1977, אבל תמיד היו קצת שונים: חליפות מחויטות, אהבה למוזיקת המודס של שנות השישים ולקינקס ולמי. האלבום השני שלהם התקבל בפושרות, ופול ולר, הכותב והזמר, היה בן עשרים בלבד וחשש שנגמרו לו הרעיונות. ב־All Mod Cons, שיצא בסוף 1978, הוא הוכיח שהחשש היה מיותר.''',
'''זה רוק מהיר ונמרץ, עם גיטרה חדה, בס מקפץ של ברוס פוקסטון ותופים של ריק באקלר, אבל גם שירים שקטים ומפתיעים. ולר כותב על אנגליה של היום־יום: על איש העסקים המנומס והמרובע ב־Mr. Clean, על הכוכב שמגלה שאף אחד לא באמת היה חבר שלו ב־To Be Someone, ועל אהבה פשוטה ב־English Rose, בלדה אקוסטית עדינה. יש גם גרסה נלהבת ל־David Watts של הקינקס, שיר על ילד בית ספר שכולם מקנאים בו. בסוף מגיע Down in the Tube Station at Midnight, סיפור מצמרר על אדם שחוזר הביתה ברכבת התחתית ונתקף בידי בריונים, בזמן שאשתו מחכה לו בבית.''',
'''האלבום הפך את הג׳אם לאחת הלהקות האהובות באנגליה, ואת ולר לאחד הכותבים החשובים של דורו, מי שמתעד את החיים הבריטיים כמו ריי דייוויס לפניו. בשנים שאחר כך הלהקה הגיעה שוב ושוב למקום הראשון במצעד הסינגלים. באמריקה הם כמעט לא הצליחו, ובאנגליה הם נשארים אגדה.''',
'''את David Watts המקורי תמצאו אצל הקינקס ב־Something Else (אלבום 97). השוו את שתי הגרסאות, ואחר כך הקשיבו ל־Down in the Tube Station at Midnight כמו לסיפור קצר, מההתחלה ועד הסוף.''',
], [
('English Rose', 'בלדה אקוסטית עדינה ויפה, הפתעה שקטה באמצע אלבום נמרץ ומהיר.'),
('David Watts', 'גרסה נלהבת לשיר של הקינקס על הילד שכולם בבית הספר מקנאים בו.'),
('Down in the Tube Station at Midnight', 'סיפור קצר ומצמרר על נסיעה לילית ברכבת התחתית של לונדון.'),
])

add(402, [
'''ג׳ו איליי גדל בלאבוק, עיר שטוחה ומאובקת במערב טקסס, והתחיל את דרכו בתחילת שנות השבעים בלהקה קטנה בשם The Flatlanders, יחד עם שני חברים כותבי שירים, ג׳ימי דייל גילמור ובאץ׳ הנקוק. הלהקה כמעט לא נשמעה מחוץ לטקסס, אבל השירים שכתבו נשארו איתו. Honky Tonk Masquerade, אלבומו השני, יצא ב־1978 ונחשב לטוב שבאלבומיו.''',
'''זה קאנטרי של בארים טקסניים, אבל עם אנרגיה של רוק: גיטרת סטיל מיללת של לויד מיינס, אקורדיון שמביא טעם מקסיקני, וקצב שמתאים לריקוד. חלק מהשירים הטובים באלבום נכתבו בידי באץ׳ הנקוק: West Texas Waltz הוא ואלס שובב ומצחיק, She Never Spoke Spanish to Me הוא שיר אהבה מתוק־מר עם ניחוח של הגבול המקסיקני, ו־Boxcars הוא שיר מלנכולי על קרונות רכבת ועל חלומות שנוסעים הלאה. שיר הנושא, שאיליי כתב בעצמו, הוא בלדה על אנשים שמסתתרים מאחורי מסכות בבר של יום שבת בלילה. הקול של איליי חם ומחוספס, והלהקה שלו נשמעת כמו חבורה שמנגנת יחד כבר שנים.''',
'''האלבום לא הפך ללהיט גדול, אבל הוא נחשב לאחד השיאים של הקאנטרי הטקסני הבועט של שנות השבעים. מוזיקאי פאנק בריטים גילו אותו, והקלאש אף לקחו את איליי איתם להופעות. הוא הראה שאפשר לחבר בין מסורת קאנטרי ישנה לבין רוקנרול מהיר, בלי לוותר על אף אחד מהם.''',
'''אם אהבתם את Red Headed Stranger של ווילי נלסון (אלבום 345), כאן תשמעו טקסס אחרת, צעירה ורועשת יותר. התחילו בשיר הנושא ואחר כך עברו ל־West Texas Waltz, ונסו לא לרקוד.''',
], [
('Honky Tonk Masquerade', 'בלדה על אנשים שמסתתרים מאחורי מסכות בבר של יום שבת בלילה.'),
('West Texas Waltz', 'ואלס שובב ומצחיק של באץ׳ הנקוק, עם אקורדיון שקשה לא לרקוד אליו.'),
('Boxcars', 'שיר מלנכולי ויפה על קרונות רכבת ועל חלומות שנוסעים הלאה בלעדינו.'),
])

add(403, [
'''האדוורטס היו מהלהקות הראשונות של הפאנק הלונדוני, והופיעו כבר ב־1977 במועדון The Roxy המפורסם. את השירים כתב ושר טי. וי. סמית׳, ואת הבס ניגנה חברתו גיי אדוורט, מהנשים הראשונות שהפכו לפנים של הפאנק. הסינגל Gary Gilmore's Eyes, על אדם שמקבל השתלת עיניים מרוצח שהוצא להורג, הכניס אותם למצעד. Crossing the Red Sea with the Adverts, אלבומם הראשון, יצא בתחילת 1978.''',
'''הצליל פשוט וישיר: גיטרות מהירות, תופים דוהרים והקול הנרגש של סמית׳. אבל המילים חכמות יותר מהרגיל בפאנק. One Chord Wonders, הפותח, צוחק על הלהקה עצמה, להקה שיודעת רק אקורד אחד ומופיעה מול קהל משועמם. Bored Teenagers הוא המנון לבני נוער שאין להם מה לעשות, ו־No Time to Be 21 מתאר את הפחד להתבגר בעולם שאין בו מקום בשבילך. ו־Great British Mistake חותם את התקליט בכעס על אנגליה של אותם ימים. כמעט כל השירים קצרים, שתיים או שלוש דקות, ונגמרים לפני שמספיקים להתעייף מהם.''',
'''הלהקה התפרקה אחרי אלבום נוסף אחד, אבל התקליט הזה נחשב לאחד האלבומים הטובים של הפאנק הבריטי הראשון, לצד אלבומי הקלאש והסקס פיסטולס. סמית׳ המשיך לכתוב ולהופיע במשך עשרות שנים, וגיי אדוורט נשארה דמות אייקונית בזכות מראה חד ובס פשוט ובטוח.''',
'''שמעו אותו אחרי אלבום הבכורה של הקלאש (אלבום 376), ושימו לב למילים של סמית׳. בין כל הצעקות מסתתר כותב שנון, עצוב ומצחיק גם יחד.''',
], [
('One Chord Wonders', 'הפותח: להקה שיודעת אקורד אחד בלבד צוחקת על עצמה ועל הקהל.'),
('Bored Teenagers', 'המנון מהיר ונרגש לבני נוער משועממים שאין להם שום מקום ללכת.'),
('No Time to Be 21', 'שיר על הפחד להתבגר בעולם שנראה שאין בו מקום בשבילך.'),
])

add(404, [
'''אחרי שני אלבומים שכמעט לא נמכרו, ביג סטאר (אלבום 242) התפרקה כמעט לגמרי. ב־1974 נשארו בממפיס רק אלכס צ׳ילטון והמתופף ג׳ודי סטיבנס, והם נכנסו לאולפן עם המפיק ג׳ים דיקינסון. צ׳ילטון היה במצב רוח קודר ומבולבל, והשירים שכתב היו שבורים ומוזרים. חברות התקליטים לא ידעו מה לעשות עם ההקלטות, והן יצאו רק ב־1978, תחת השם Third או Sister Lovers, על שם שתי האחיות שצ׳ילטון וסטיבנס יצאו איתן אז.''',
'''זה אלבום שביר, יפה ולפעמים מפחיד. יש בו שירי פופ מתוקים, כמו Thank You Friends, עם מקהלה וכלי מיתר, שנשמע כמו תודה חמה אבל גם קצת לעגנית. Big Black Car הוא נסיעה איטית בלילה, ו־Kanga Roo נבנה מגיטרה, רעשים וקול חלש, כמעט כמו חלום. Holocaust הוא אחד השירים העצובים ביותר שנכתבו ברוק, בפסנתר איטי ובקול עייף. צ׳ילטון גם שר גרסה עדינה ל־Femme Fatale של הוולווט אנדרגראונד (אלבום 91). ההפקה של דיקינסון משאירה את כל הסדקים גלויים, ומוסיפה כלי מיתר וקישוטים דווקא ברגעים הכי שבורים.''',
'''בזמנו כמעט אף אחד לא שמע את האלבום, אבל עם השנים הוא הפך לאבן יסוד לרוק האלטרנטיבי. להקות רבות כיסו שירים ממנו, ורבים רואים בו את אחד האלבומים הכנים והחשופים ביותר ברוק. אין לו סדר שירים סופי, ובכל הוצאה הוא נראה קצת אחרת.''',
'''שמעו אותו בשעת לילה, בשקט. התחילו ב־Thank You Friends, ואחר כך תנו ל־Holocaust ול־Kanga Roo לשקוע לאט.''',
], [
('Thank You Friends', 'שיר פופ מתוק עם מקהלה ומיתרים, תודה חמה עם קורטוב של לעג.'),
('Kanga Roo', 'גיטרה, רעשים וקול חלש כמעט כמו חלום, מהשירים המוזרים והיפים באלבום.'),
('Holocaust', 'פסנתר איטי וקול עייף, מהשירים העצובים והחשופים ביותר שנכתבו ברוק.'),
])

add(405, [
'''הרזידנטס, מסן פרנסיסקו, הם אחת הלהקות המסתוריות בעולם: כבר עשרות שנים לא ידוע בוודאות מי חבריה. הם הופיעו בתחפושות, ובעיקר במסכות ענקיות של גלגלי עיניים, וטענו שהזהות שלהם לא חשובה, רק המוזיקה. Duck Stab/Buster & Glen, שיצא ב־1978, מאחד שני תקליטים קצרים לאלבום אחד, ונחשב לנגיש ביותר שלהם.''',
'''השירים קצרים, משונים ומצחיקים: קלידים זולים, בס מגומגם, תופים מוזרים וקולות מעוותים שנשמעים כמו דמויות מסרט מצויר מפחיד. Constantinople הוא שיר קופצני על עיר רחוקה, Hello Skinny מתאר דמות רזה ועצובה בצלילים אפלים של צעצועים, ו־Semolina נשמע כמו שיר ילדים שהשתבש. יש גם שירים על ילד ביום הולדתו, על מרימת משקולות ועל גבינה. הכול נשמע כמו מופע בובות בחדר חשוך: גם משעשע וגם קצת מאיים. הרזידנטס לא ניסו להיות יפים; הם רצו להפתיע, לבלבל ולהצחיק, ובאלבום הזה הם עושים זאת בשירים קצרים וקליטים באופן מפתיע.''',
'''הלהקה הקימה חברת תקליטים משלה, Ralph Records, ועשתה הכול בעצמה, הרבה לפני שזה היה מקובל. הרוח העצמאית והמוזרה שלה השפיעה על להקות ניסיוניות רבות, והמסכות שלהם הפכו לאחד הדימויים המוכרים ברוק הניסיוני. Duck Stab נשאר הדלת הקלה ביותר לעולם שלהם.''',
'''זה לא אלבום לכל רגע. שמעו כמה שירים בכל פעם, כמו אוסף סיפורים קצרים ומשונים. אם תאהבו אותו, תגלו שקשה להוציא את Constantinople מהראש.''',
], [
('Constantinople', 'שיר קופצני ומוזר על עיר רחוקה, שקשה מאוד להוציא אחר כך מהראש.'),
('Hello Skinny', 'דמות רזה ועצובה, בצלילים אפלים של צעצועים ומנגינה שמתגנבת מתחת לעור.'),
('Semolina', 'נשמע כמו שיר ילדים שהשתבש, מצחיק וקצת מפחיד באותה נשימה.'),
])

add(406, [
'''בתחילת 1978 הסקס פיסטולס (אלבום 393) התפרקו באמצע סיבוב הופעות באמריקה. ג׳וני רוטן חזר לשמו האמיתי, ג׳ון ליידון, והקים להקה חדשה בשם Public Image Ltd, או בקיצור PiL. איתו היו הגיטריסט קית׳ לבין, שניגן קודם לכן בגרסה מוקדמת של הקלאש, והבסיסט ג׳ה ווֹבֶּל, חבר ילדות שכמעט לא ידע לנגן כשהתחיל. First Issue, אלבומם הראשון, יצא בסוף אותה שנה.''',
'''מהשנייה הראשונה ברור שזה לא עוד תקליט פאנק. Theme, הפותח, נמשך כמעט עשר דקות: בס כבד ואיטי, גיטרה צורמת וליידון שצועק ומקונן על רצון למות. Public Image, הסינגל, מהיר וחד, וליידון יורק בו את זעמו על מי שחשבו שהם מכירים אותו מהפיסטולס. Annalisa מבוסס על סיפור אמיתי של נערה גרמנייה שמתה אחרי טקס גירוש שדים, ו־Religion מתקיף את הכנסייה במילים בוטות. הבס של ווֹבֶּל, עמוק ומושפע מדאב ורגאיי, הוא הלב של הצליל, והגיטרה של לבין נשמעת כמו מתכת שנשברת. יש גם קטע סיום ארוך ומטורף של צחוקים ורעשים, שכמעט אפשר לקרוא לו בדיחה על חשבון חברת התקליטים.''',
'''האלבום פתח את מה שנקרא אחר כך פוסט־פאנק: מוזיקה שיוצאת מהפאנק אבל מחפשת צלילים חדשים, מהדאב, מהקראוטרוק ומהרעש. Public Image הגיע לעשירייה הראשונה באנגליה, וליידון הראה שהוא יותר מסמל של מרד.''',
'''שמעו את Public Image, ואז את Theme. בהמשך, השוו לאלבום השני של הלהקה, Metal Box (אלבום 448), שבו הרעיונות האלה הולכים עוד הרבה יותר רחוק.''',
], [
('Public Image', 'הסינגל: מהיר וחד, וליידון יורק את זעמו על מי שחשבו שהם מכירים אותו.'),
('Theme', 'הפותח: כמעט עשר דקות של בס כבד, גיטרה צורמת וצעקה ארוכה.'),
('Annalisa', 'סיפור אמיתי ומטריד על נערה שמתה אחרי טקס לגירוש שדים.'),
])

add(407, [
'''הווארד דבוטו היה הזמר הראשון של הבאזקוקס (אלבום 413), אבל עזב אחרי תקליט קצר אחד כי הרגיש שהפאנק כבר נעשה צפוי. במנצ׳סטר הוא הקים להקה חדשה, מגזין, עם הגיטריסט ג׳ון מקגיוך, הבסיסט בארי אדמסון והקלידן דייב פורמולה. Real Life, אלבומם הראשון, יצא ב־1978, ונשמע כבר כמו משהו שבא אחרי הפאנק.''',
'''הצליל עשיר ומורכב יותר משל רוב להקות הפאנק: קלידים מבשרי רעות, גיטרה חדה ויצירתית של מקגיוך, בס עבה ומלודי, ומעל הכול הקול של דבוטו, קר, עוקצני ותיאטרלי. Shot by Both Sides, הסינגל, הוא שיר מהיר וחזק על אדם שנתקע בין שני מחנות ומותקף משני הצדדים; את המוזיקה שלו כתב דבוטו יחד עם פיט שלי מהבאזקוקס. Motorcade מתאר שיירת מכוניות רשמית באווירה מאיימת, ו־The Light Pours Out of Me הוא אחד השירים החזקים באלבום, בקצב דוהר ובגיטרה שצורבת. Definitive Gaze, הפותח, מתחיל בקלידים דרמטיים ונשמע כמעט כמו פתיחה של סרט, עם דבוטו שמתבונן בעולם בעיניים מפוכחות.''',
'''מגזין לא הפכו לכוכבים, אבל רבים רואים בהם את אחת הלהקות החשובות של הפוסט־פאנק. חבריה המשיכו לדרכים מרשימות: מקגיוך ניגן אחר כך עם סוזי אנד דה בנשיז (אלבום 425), ואדמסון עם ניק קייב. להקות רבות של שנות השמונים למדו מהם איך לשלב קלידים ודרמה ברוק חד.''',
'''שמעו את Shot by Both Sides ואחר כך את גרסת הבאזקוקס לאותה מנגינה, Lipstick. מעניין לשמוע איך אותו רעיון הופך לשני שירים שונים לגמרי.''',
], [
('Shot by Both Sides', 'שיר מהיר וחזק על אדם שתקוע בין שני מחנות ונפגע משני הצדדים.'),
('Motorcade', 'שיירת מכוניות רשמית באווירה מאיימת, עם קלידים ובס כבדים ודרמטיים.'),
('The Light Pours Out of Me', 'קצב דוהר, גיטרה צורבת ודבוטו במיטבו, מהשירים החזקים באלבום.'),
])

add(408, [
'''אחרי ההצלחה של Born to Run (אלבום 334), ברוס ספרינגסטין נקלע למאבק משפטי עם המנהל הקודם שלו, ובמשך כשנה לא יכול היה להקליט. כשסוף סוף חזר לאולפן, הוא כתב עשרות שירים ובחר מתוכם רק עשרה, הקשים והרציניים ביותר. Darkness on the Edge of Town יצא ב־1978, והוא אלבום בוגר ומפוכח יותר מקודמו.''',
'''במקום החלומות הגדולים על בריחה במכונית, כאן יש אנשים שנשארים: עובדי מפעלים, בנים שלא מסתדרים עם אבותיהם, זוגות שמנסים להחזיק מעמד. הצליל חשוף ומחוספס יותר, עם גיטרות חדות, פסנתר ואורגן, והקול של ספרינגסטין נשמע עייף וכועס. Badlands, הפותח, הוא המנון סוחף על עמידה מול חיים קשים, ו־The Promised Land מתחיל במפוחית ונשמע כמו תפילה של אדם שממשיך להאמין. Racing in the Street הוא שיר ארוך ועצוב על בחור שמתחרה במכוניות בלילות, בזמן שחברתו יושבת בבית ובוכה. Factory, קצר ופשוט, מתאר את אביו של ספרינגסטין הולך בכל בוקר לעבודה במפעל, ושיר הנושא סוגר את האלבום בנחישות שקטה.''',
'''האלבום הפך לאחד האהובים של ספרינגסטין על מעריציו, ורבים רואים בו את לב העבודה שלו: שירים על כבוד, על עבודה ועל תקווה שאינה תמימה. השירים הרבים שלא נכנסו אליו יצאו רק כעבור יותר משלושים שנה, ומתברר שהוא ויתר גם על להיטים בדרך.''',
'''שמעו אותו ברצף, מ־Badlands ועד שיר הנושא. אם יש לכם זמן לשיר אחד, בחרו ב־Racing in the Street, והקשיבו לפסנתר שממשיך הרבה אחרי שהמילים נגמרות.''',
], [
('Badlands', 'הפותח: המנון סוחף על עמידה עיקשת מול חיים קשים, בגיטרה ובאורגן.'),
('Racing in the Street', 'שיר ארוך ועצוב על מרוצי מכוניות בלילה, עם פסנתר שממשיך אחרי המילים.'),
('The Promised Land', 'נפתח במפוחית ונשמע כמו תפילה של אדם שממשיך להאמין, למרות הכול.'),
])

add(409, [
'''פאנקדליק, הלהקה של ג׳ורג׳ קלינטון, הייתה האחות הפרועה והרוקיסטית של פרלמנט (אלבום 360). שתי הלהקות חלקו נגנים ורעיונות, ויחד נקראו פי־פאנק. ב־1978, אחרי שנים של אלבומים ניסיוניים ולא תמיד מצליחים, פאנקדליק הוציאו את One Nation Under a Groove, האלבום המצליח ביותר שלהם.''',
'''שיר הנושא, שקלינטון כתב יחד עם חברי הלהקה, ובהם הקלידן וולטר "ג׳וני" מוריסון, הוא אחד משירי הפאנק הגדולים שנכתבו: קצב מתגלגל, בס עבה, מקהלה של קולות וקריאה לאחדות סביב הגרוב, כלומר סביב הריקוד והמוזיקה. הוא נמשך כשבע וחצי דקות ולא מאבד לרגע את הכוח. Who Says a Funk Band Can't Play Rock?! עונה בדיוק לשאלה שבשם: גיטרות רוק כבדות על קצב פאנק, ומייקל המפטון, גיטריסט צעיר, מראה שהוא יכול לנגן כמו אלוהי הרוק. יש גם שיר עם שם ארוך ומגוחך שכולו בדיחה גסה, שיר אהבה חלק, Into You, וסיום שמח וקופצני בשם Cholly. הכול נשמע כמו מסיבה גדולה, מלאה חוש הומור, שמעולם לא לוקחת את עצמה ברצינות מלאה.''',
'''שיר הנושא הגיע למקום הראשון במצעד הרית׳ם אנד בלוז האמריקאי ונשאר שם שבועות רבים, והאלבום נמכר במיליון עותקים. מאז הוא נחשב לאחד השיאים של הפאנק, והקצבים שלו נדגמו אחר כך שוב ושוב בידי אמני היפ־הופ.''',
'''השוו אותו ל־Maggot Brain (אלבום 230), האלבום הפסיכדלי והאפל של אותה להקה משבע שנים קודם. זה אותו צוות, במצב רוח שונה לגמרי. ושמעו את שיר הנושא בווליום גבוה.''',
], [
('One Nation Under a Groove', 'קריאה לאחדות סביב הריקוד: שבע וחצי דקות של פאנק שלא מאבד כוח.'),
('Who Says a Funk Band Can\'t Play Rock?!', 'גיטרות רוק כבדות על קצב פאנק, תשובה בועטת לשאלה שבשם השיר.'),
('Cholly (Funk Getting Ready to Roll!)', 'סיום שמח וקופצני, מסיבה קטנה שחותמת את האלבום בחיוך.'),
])

add(410, [
'''ת׳רובינג גריסל, רביעייה לונדונית, התחילו כקבוצת אמנות מופע שהופיעה בגלריות ועוררה שערוריות. היו בה ג׳נסיס פי־אוריג׳, קוזי פאני טוטי, כריס קרטר ופיטר כריסטופרסון. הם הקימו חברת תקליטים בשם Industrial Records, ומשמה נולד המונח "מוזיקה תעשייתית". D.o.A.: The Third and Final Report, שיצא ב־1978, הוא אלבומם השלישי.''',
'''זו לא מוזיקה במובן הרגיל. יש כאן רעשים של מכונות, סינתיסייזרים בנויים ביד, הקלטות שיחות טלפון, קולות מעוותים וקטעים מוזיקליים עדינים שצצים פתאום באמצע. Hamburger Lady, אחד הקטעים המפורסמים שלהם, מבוסס על מכתב שתיאר אישה בבית חולים לכוויות, וקולו המעוות של פי־אוריג׳ מרחף מעל צליל מזמזם ומאיים. AB/7A, לעומת זאת, הוא קטע סינתיסייזר מלודי ונעים כמעט, שמרמז על המוזיקה האלקטרונית שתבוא. Weeping הוא קטע איטי ועצוב מאוד, כמעט קינה. יש באלבום גם קטעים שכל חבר הכין לבד, וגם גרסה מואצת של שיר האהבה United, שנדחס לשניות בודדות, כמו בדיחה על ציפייה של המאזין.''',
'''ת׳רובינג גריסל היו מקור השראה לדור שלם של מוזיקאים ניסיוניים ואלקטרוניים, מלהקות תעשייתיות קשוחות ועד מוזיקת טכנו. הם הראו שאפשר להשתמש ברעש, בטכנולוגיה ובחומרים מטרידים כחומר אמנותי, ובחלק מהקטעים שלהם כבר נשמע צליל שיעצב עשורים של מוזיקה.''',
'''זה אלבום קשה, ולא לכל אחד. התחילו ב־AB/7A, העדין מכולם, ואחר כך נסו את Hamburger Lady באוזניות, רק אם אתם מוכנים לחוויה לא נוחה.''',
], [
('Hamburger Lady', 'קטע מזמזם ומאיים על אישה בבית חולים לכוויות, מהמפורסמים שלהם.'),
('AB/7A', 'קטע סינתיסייזר מלודי ונעים כמעט, שמרמז על המוזיקה האלקטרונית שתבוא.'),
('Weeping', 'קטע איטי ועצוב מאוד, כמעט קינה, ברגע שקט באלבום רועש.'),
])
